"""Render the buildless Fluent Minds library. Run with Python 3, no dependencies."""
import json, re, math
from html import escape as e
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
articles=json.loads((ROOT/'content/articles.json').read_text())
base=(ROOT/'finding-support.html').read_text()
style=re.search(r'<style>[\s\S]*?</style>',base)[0]
fonts=re.search(r'<link rel="preconnect"[\s\S]*?(?=\s*<style>)',base)[0]
nav=re.search(r'<nav>[\s\S]*?</nav>',base)[0].replace(' class="active"','')
if 'bangladesh-therapy.html' not in nav:
 nav=nav.replace('<a href="resources.html">Resources</a>','<a href="resources.html">Resources</a><a href="bangladesh-therapy.html">Bangladesh Therapy</a>')
footer='<footer class="library-footer"><span>© 2026 Fluent Minds · Every voice deserves time.</span><div><a href="blog.html">Articles</a><a href="resources.html">Resources</a><a href="bangladesh-therapy.html">Bangladesh Therapy</a><a href="contact.html">Contact</a></div></footer>'
labels={'daily':'Daily Life','confidence':'Confidence','mental':'Mental Health','techniques':'Techniques','research':'Research'}
def page(title,desc,body):
 return '<!DOCTYPE html>\n<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+e(desc,quote=True)+'"><title>'+e(title)+' — Fluent Minds</title>'+fonts+style+'<link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head><body><a class="skip-link" href="#main-content">Skip to content</a>'+nav+body+footer+'</body></html>\n'
def hero(tag,title,desc):
 return '<header class="page-hero"><span class="page-tag">'+e(tag)+'</span><h1>'+e(title)+'</h1><p>'+e(desc)+'</p></header>'
def card(a):
 words=len(re.sub('<[^>]*>',' ',''.join(s['body'] for s in a['sections'])).split())
 return '<a href="'+a['slug']+'.html" class="blog-card" data-cat="'+a['category']+'"><div class="blog-card-body"><span class="cat-badge">'+labels[a['category']]+'</span><h3>'+e(a['title'])+'</h3><p>'+e(a['excerpt'])+'</p><span class="reading-meta">'+str(max(2,math.ceil(words/180)))+' min read · Updated 18 Nov 2026</span><span class="blog-card-read">Read guide</span></div></a>'
for i,a in enumerate(articles):
 toc=''.join('<a href="#'+s['id']+'">'+e(s['heading'])+'</a>' for s in a['sections'])
 sections=''.join('<section><h2 id="'+s['id']+'">'+e(s['heading'])+'</h2>'+s['body']+'</section>' for s in a['sections'])
 sources=''.join('<li><a href="'+e(url,quote=True)+'">'+e(label)+'</a></li>' for url,label in a['sources'])
 related=[b for b in articles if b['category']==a['category'] and b!=a][:3]
 if len(related)<3:related += [b for b in articles if b not in related and b!=a][:3-len(related)]
 body=hero(labels[a['category']],a['title'],a['excerpt'])+'<main class="editorial" id="main-content" tabindex="-1"><p class="reading-meta">Fluent Minds educational guide · Updated 18 November 2026</p><div class="editorial-grid"><article><p class="guide-note">Practical education and planning ideas, not individual treatment. These guides have not been clinically reviewed. A qualified speech-language professional can help you choose support that fits your needs.</p>'+sections+'<section class="source-list"><h2 id="sources">Sources &amp; further reading</h2><p>Sources provide background; example scripts and checklists are Fluent Minds planning suggestions. International services and education policies may differ from Bangladesh.</p><ul>'+sources+'</ul></section><section><h2>Keep exploring</h2><div class="guide-links">'+''.join('<a href="'+b['slug']+'.html">'+e(b['title'])+' →</a>' for b in related)+'</div></section><div class="guide-actions"><button type="button" data-print>Print / save as PDF</button><a href="blog.html">← All articles</a></div></article><aside class="article-outline"><h2>In this guide</h2><div class="guide-links">'+toc+'<a href="#sources">Sources &amp; further reading</a></div><div class="guide-note"><strong>Looking for local care?</strong><p>Find official provider information and contact options.</p><a href="bangladesh-therapy.html">Speech therapy in Bangladesh →</a></div><div class="guide-links"><a href="resources.html#downloads">Download worksheets</a><a href="daily-practice.html">Create a speaking plan</a></div></aside></div></main>'
 (ROOT/(a['slug']+'.html')).write_text(page(a['title'],a['excerpt'],body))
# Retain existing blog styles but render all cards into one genuinely filterable library.
p=ROOT/'blog.html'; t=p.read_text(); head=t[:t.index('<body>')]
head=re.sub(r'<meta name="description"[^>]*>','',head).replace('</head>','<meta name="description" content="Explore 26 practical articles and guides about stuttering, student life, family support, and finding speech therapy."></head>')
filters='<div class="filters" role="group" aria-label="Article topics">'+''.join('<button type="button" class="filter-btn'+(' active' if cat=='all' else '')+'" data-filter="'+cat+'" aria-pressed="'+str(cat=='all').lower()+'">'+label+'</button>' for cat,label in [('all','All Articles')]+list(labels.items()))+'</div>'
search='<div class="library-search"><label for="article-search">Search articles</label><input type="search" id="article-search" placeholder="Try viva, Bangla, parents, or interviews" aria-controls="blogGrid"><button type="button" data-reset="articles">Clear search &amp; filters</button><p id="article-count" role="status" aria-live="polite">26 articles and guides</p></div>'
extras=''.join('<a class="blog-card" data-cat="'+cat+'" href="'+url+'"><div class="blog-card-body"><span class="cat-badge">'+labels[cat]+'</span><h3>'+title+'</h3><p>'+desc+'</p><span class="blog-card-read">Read guide</span></div></a>' for cat,url,title,desc in [('daily','daily-practice.html','Small steps, at your pace','Choose a meaningful participation goal and download a personal speaking plan.'),('confidence','supporting-someone.html','Give every voice time','Supportive listening for friends, families, and teachers.'),('mental','finding-support.html','Find help that fits you','Questions for professional care and peer support.')])
body=hero('The Fluent Minds library','Practical guides for everyday life','Explore 20 new articles alongside our existing guides. Find ideas for study, work, family conversations, and getting support.')+'<main id="main-content" tabindex="-1">'+filters+search+'<div class="blog-main"><div class="blog-grid" id="blogGrid">'+''.join(card(a) for a in articles)+extras+'</div><p id="article-empty" class="filter-empty" hidden>No articles match. Try another keyword or clear your filters.</p><div class="guide-note"><h2>Need a place to start?</h2><p><a href="article-first-appointment.html">Prepare for a first appointment</a> · <a href="bangladesh-therapy.html">Find therapy in Bangladesh</a> · <a href="resources.html#downloads">Get free worksheets</a></p></div></div></main>'
p.write_text(head+'<body><a class="skip-link" href="#main-content">Skip to content</a>'+nav+body+footer+'</body></html>\n')
# Directory entries use CRP's official centre listing and SLT department page.
centres=[
 ('CRP Savar','Dhaka','Chapain, Savar, Dhaka 1343','01730059555'),
 ('CRP Mirpur','Dhaka','Plot A/5, Block A, Section 14, Mirpur, Dhaka','01768152922'),
 ('CRP Chattogram — A.K. Khan Centre','Chattogram','Kalurghat, Mohora, Chattogram','01730059529'),
 ('CRP Rajshahi — Afsar Hussain Centre','Rajshahi','Mahisbathan, Rajshahi Court, Rajpara','01730059644'),
 ('CRP Barishal — CARSA Foundation Centre','Barishal','12 Gonopara, Kashipur, Barishal','01730059643'),
 ('CRP Sylhet — Iskandar Shitara Centre','Sylhet','House 26, Main Road, Block C, Shahjalal Upashahar','01730059512'),
 ('CRP Gobindapur','Moulvibazar','Gobindapur, Kajoldhara, Kulaura, Moulvibazar','01730059542'),
 ('CRP Moulvibazar — Afsarul & Aktarul Haque Centre','Moulvibazar','Nitessor, Mokambazar, Giasnagar, Moulvibazar Sadar','01730059628'),
 ('CRP Mymensingh — BAU Centre','Mymensingh','Beside Sultana Rajia Hall, Bangladesh Agricultural University','01730059510'),
 ('CRP Manikganj','Dhaka','12 Shantanu Roy Sarani, Dashora, Manikganj','01730059559'),
 ('CRP Pabna — Diabetic Shamity Centre','Rajshahi','Gachpara bypass intersection, Pabna 6600','01730059518')]
providers=[dict(name=n,region=r,address=a,phone='+880'+p[1:],display=p,kind='CRP regional service',desc='CRP lists speech-language therapy in this area. Confirm local sessions, ages served, and stuttering experience before visiting.',url='https://crp-bangladesh.org/crp-centers',service='https://www.crp-bangladesh.org/therapy/speech-language-therapy-dept') for n,r,a,p in centres]
providers += [
 dict(name='Evercare Dhaka — Rehabilitation',region='Dhaka',address='Plot 81, Block E, Bashundhara R/A, Dhaka 1229',phone='10678',display='10678',kind='Hospital rehabilitation',desc='Official rehabilitation department page lists speech therapy. Ask about your age group and stuttering-specific appointments.',url='https://www.evercarebd.com/en/dhaka/specialities/physical-medicine-rehabilitation'),
 dict(name='Evercare Dhaka — Child Development Centre',region='Dhaka',address='Plot 81, Block E, Bashundhara R/A, Dhaka 1229',phone='10678',display='10678',kind='Children: newborn to 16 years',desc='Lists a speech therapy and language/communication clinic. Confirm assessment criteria and appointment availability.',url='https://www.evercarebd.com/en/dhaka/specialities/child-development-centre'),
 dict(name='Square Child Development Centre',region='Dhaka',address='18/F Bir Uttam Qazi Nuruzzaman Sarak, West Panthapath, Dhaka 1205',phone='10616',display='10616',kind='Children and families',desc='Official CDC page lists speech therapy. Contact the hospital to confirm location, age suitability, and experience with stuttering.',url='https://www.squarehospital.com/page/29/square-child-development-centre-%28cdc%29')]
(ROOT/'content/providers.json').write_text(json.dumps(providers,ensure_ascii=False,indent=2)+'\n')
from urllib.parse import urlencode
cards=''
for x in providers:
 maps='https://www.google.com/maps/search/?'+urlencode({'api':'1','query':x['name']+' '+x['address']})
 cards+='<article class="resource-card provider-card" data-region="'+x['region']+'"><span class="resource-type">'+e(x['kind'])+'</span><h2>'+e(x['name'])+'</h2><p class="provider-location">'+e(x['address'])+'</p><p>'+e(x['desc'])+'</p><div class="provider-actions"><a href="tel:'+x['phone']+'">Call '+x['display']+'</a><a href="'+e(x['url'],quote=True)+'">Official '+('centre contacts' if x.get('service') else 'service page')+' →</a><a href="'+e(maps,quote=True)+'">Find on map →</a>'+('<a href="'+x['service']+'">Speech therapy services →</a>' if x.get('service') else '')+'</div></article>'
regions=sorted(set(x['region'] for x in providers))
body=hero('Local support · বাংলাদেশ','Speech therapy in Bangladesh','Official provider information, regional contacts, and questions to help you find suitable care.')+'<main id="main-content" tabindex="-1" class="directory-main"><div class="guide-note"><strong>Checked against official pages on 18 November 2026.</strong><p>These are service leads, not endorsements or confirmed bookings. Call first to confirm a qualified therapist, stuttering experience, ages, Bangla/English support, fees, referral requirements, and current sessions. Regional availability can change; do not travel without confirming. Hospital short codes are for calls within Bangladesh.</p><p lang="bn">যাওয়ার আগে ফোন করে স্পিচ থেরাপিস্টের যোগ্যতা, তোতলামি নিয়ে কাজের অভিজ্ঞতা, বয়সসীমা, ফি ও অ্যাপয়েন্টমেন্ট নিশ্চিত করুন।</p></div><div class="directory-tools"><div><label for="therapy-search">Search name, city, or service</label><input type="search" id="therapy-search" placeholder="Try Mirpur, Savar, child, or Sylhet" aria-controls="provider-grid"></div><div><label for="therapy-region">Region / division</label><select id="therapy-region" aria-controls="provider-grid"><option value="all">All regions</option>'+''.join('<option>'+r+'</option>' for r in regions)+'</select></div><button type="button" data-reset="providers">Clear filters</button></div><p id="provider-count" class="results-count" role="status" aria-live="polite">14 service locations / departments</p><div class="resources-grid" id="provider-grid">'+cards+'</div><p id="provider-empty" class="filter-empty" hidden>No providers match. Clear your filters or contact CRP / SSLT for information about local services.</p><section class="guide-note"><h2>Need help finding a qualified professional?</h2><p><a href="https://sslt.org.bd/">Society of Speech &amp; Language Therapists (SSLT)</a> is a Bangladesh professional body, not an appointment clinic. Ask about professional information and how to check a therapist’s qualifications.</p><p><a href="https://crp-bangladesh.org/crp-centers">CRP official centre directory</a> · <a href="https://www.crp-bangladesh.org/therapy/speech-language-therapy-dept">CRP speech-language therapy service description</a></p></section><section class="directory-help"><h2>Before booking</h2><ol><li>Describe the support you want and your age group.</li><li>Ask about qualifications and experience with stuttering in your language.</li><li>Confirm appointment time, exact location, assessment fee, and follow-up costs.</li><li>Ask whether remote sessions or reduced-fee services are available; do not assume they are.</li><li>Bring your questions and any previous reports you choose to share.</li></ol><div class="guide-links"><a href="article-first-appointment.html">Read the first-appointment guide →</a><a href="downloads/appointment-checklist.txt" download>Download the appointment checklist (.txt) →</a><a href="contact.html?subject=Request+a+Resource">Suggest a correction or provider →</a></div></section></main>'
(ROOT/'bangladesh-therapy.html').write_text(page('Speech therapy in Bangladesh','Find official speech-language therapy services in Bangladesh, including CRP regional centres, Evercare, and Square, with phone and map links.',body))
# Downloadable templates are plain text so they can be edited without special software.
worksheets={
 'support-plan':('Personal communication support plan','Situations I want to participate in:\n\nWhat I want to communicate:\n\nSupports that help me:\n\nWhat I want a listener to know:\n\nWhat I prefer to keep private:\n\nOne person I can ask for support:\n\nMy next step and review date:\n'),
 'appointment-checklist':('Speech therapy appointment checklist','Provider and therapist:\n\nAppointment date, time, exact address / remote link:\n\nQualifications and stuttering experience in my age group:\n\nLanguages used in assessment and therapy:\n\nAssessment fee, follow-up fees, cancellation policy:\n\nReferral / report requirements:\n\nMy priorities and questions:\n\nAgreed goals and review date:\n\nNext step:\n'),
 'teacher-conversation':('Conversation with a teacher or tutor','Dear __________________,\n\nI stutter and would like to discuss support for __________________.\n\nIt would help me if __________________.\n\nCould we discuss the format, assessment criteria, and possible arrangements?\n\nPlease check with me before sharing this information with others.\n\nAgreed next steps:\n\nReview date:\n'),
 'phone-call-planner':('Phone call planner','Who I am calling and why:\n\nReference / appointment number:\n\nThree things I need to ask:\n1.\n2.\n3.\n\nOptional opening: I stutter; please give me time to finish.\n\nInformation I received:\n\nName / department and callback details:\n\nNext step:\n')}
for slug,(title,text) in worksheets.items():
 (ROOT/'downloads'/f'{slug}.txt').write_text('FLUENT MINDS | '+title+'\n\n'+text+'\nOptional planning resource, not individual treatment. Keep personal details private on shared devices.\nhttps://fluent-minds.netlify.app/resources.html\n')
external=[
 ('Understanding stuttering','NIDCD: Stuttering','Causes, assessment, treatment, and research explained by the US National Institute on Deafness and Other Communication Disorders.','https://www.nidcd.nih.gov/health/stuttering'),
 ('Clinical reference','ASHA clinical practice portal','Professional guidance with references on stuttering, cluttering, assessment, and individualised care.','https://www.asha.org/practice-portal/clinical-topics/fluency-disorders/'),
 ('For listeners','Six tips for supportive conversations','A short Stuttering Foundation guide to giving someone time and listening to their message.','https://www.stutteringhelp.org/6-tips-speaking-someone-who-stutters'),
 ('Free books','Stuttering Foundation e-books','A free reading and download collection for different audiences. Choose material suited to your age and needs.','https://www.stutteringhelp.org/free-e-books'),
 ('Stammering support','STAMMA help hub','UK charity guidance for people who stammer, families, educators, and services. UK service and legal details may not apply in Bangladesh.','https://stamma.org/get-help'),
 ('Students','University and college support','STAMMA’s UK guide offers ideas for discussing seminars, presentations, and oral exams. Confirm your own institution’s policies.','https://stamma.org/get-help/people-who-stammer/education/help-stammering-university-college'),
 ('School','Stammering at school','STAMMA guidance for school students. Use discussion ideas locally; UK rights and services are specific to that setting.','https://stamma.org/get-help/people-who-stammer/education/school'),
 ('Peer community','National Stuttering Association','US-based peer support, resources, and events. Check each programme’s eligibility, location, fees, and time zone.','https://www.westutter.org/'),
 ('Youth and families','Friends','US-based organisation with youth and family support and virtual programmes. Confirm age and international eligibility with organisers.','https://friendswhostutter.org/'),
 ('Listen and learn','StutterTalk podcast','Conversations with people who stutter and professionals. Personal experiences and discussion are not individual treatment.','https://stuttertalk.com/'),
 ('Bangladesh profession','Society of Speech & Language Therapists','A professional body for information about speech-language therapy in Bangladesh; not an appointment clinic.','https://sslt.org.bd/'),
 ('Bangladesh services','CRP speech-language therapy','Official description of CRP’s speech-language therapy services. Use the local directory to find regional contacts.','https://www.crp-bangladesh.org/therapy/speech-language-therapy-dept')]
(ROOT/'content/resources.json').write_text(json.dumps(external,ensure_ascii=False,indent=2)+'\n')
downloads=[('7-day relaxation log','Optional comfort notes; no breath holding or fluency targets.','breathing-chart.pdf','PDF'),('Speaking preparation worksheet','Plan your message, support, rehearsal, and reflection.','speaking-preparation.pdf','PDF'),('Confidence journal','Thirty optional prompts for a notebook or notes app.','confidence-journal.pdf','PDF'),('Participation tracker','An editable seven-day tracker for goals and what helped.','practice-tracker.csv','CSV'),('Communication support plan','Put your preferences, contexts, and next steps in one editable page.','support-plan.txt','TXT'),('Appointment checklist','Questions about qualifications, costs, languages, and next steps.','appointment-checklist.txt','TXT'),('Teacher conversation template','Adapt a message to discuss classroom support privately.','teacher-conversation.txt','TXT'),('Phone call planner','Keep questions, reference numbers, and callback details together.','phone-call-planner.txt','TXT')]
def resource(title,desc,url,tag,download=False):
 return '<article class="resource-card"><span class="resource-type">'+e(tag)+'</span><h3>'+e(title)+'</h3><p>'+e(desc)+'</p><a class="resource-link" href="'+e(url,quote=True)+'"'+(' download' if download else '')+'>'+('Download '+tag if download else 'Open resource')+' →</a></article>'
body=hero('Free tools & trusted reading','Resources for your next step','Find local care, download practical worksheets, and explore trusted organisations in one place.')+'<main id="main-content" tabindex="-1" class="resources-main"><nav class="section-jumps" aria-label="Resource sections"><a href="#start">Start here</a><a href="bangladesh-therapy.html">Bangladesh therapy</a><a href="#downloads">Free downloads</a><a href="#organisations">Trusted reading</a><a href="#questions">Common questions</a></nav><section id="start"><span class="section-label">Choose your route</span><h2 class="section-title">Start with what you need</h2><div class="resources-grid">'+resource('I want practical ideas','Browse 26 articles and guides, with search and five topics.','blog.html','Read')+resource('I want support in Bangladesh','Explore 14 service locations / departments with official links, phone contacts, maps, and regional filters.','bangladesh-therapy.html','Local care')+resource('I support someone who stutters','Start with listening, classroom, and family conversation guidance.','supporting-someone.html','For allies')+'</div></section><section id="downloads"><span class="section-label">No signup required</span><h2 class="section-title">Free, usable downloads</h2><p class="section-intro">Download files directly, edit the text templates, or print the PDFs. You choose what to record and share. Keep sensitive details off shared devices.</p><div class="resources-grid">'+''.join(resource(title,desc,'downloads/'+file,tag,True) for title,desc,file,tag in downloads)+'</div><div class="guide-links"><a href="daily-practice.html">Create and download a personal speaking plan →</a></div></section><section id="organisations"><span class="section-label">Checked 18 November 2026</span><h2 class="section-title">Trusted reading &amp; communities</h2><p class="section-intro">External organisations manage their own content and services. International programmes may have age, location, or time-zone restrictions.</p><div class="resources-grid">'+''.join(resource(title,desc,url,tag) for tag,title,desc,url in external)+'</div></section><section id="questions" class="faq-section"><h2 class="section-title">Common questions</h2>'+''.join('<details><summary>'+q+'</summary><p>'+answer+'</p></details>' for q,answer in [
 ('Can I read and download without an account?','Yes. All public guides, worksheets, and directory listings are available without signing up.'),
 ('Does Fluent Minds provide therapy or make bookings?','No. This is an educational resource. Use the official links and contact details to ask providers about assessment, qualifications, fees, and appointments.'),
 ('How do I choose a therapist?','Ask about qualifications, experience with stuttering in your age group and languages, collaborative goals, fees, and review points. Read our <a href="article-first-appointment.html">first-appointment guide</a>.'),
 ('Are the Bangladesh services guaranteed to be available?','No. The directory reflects official published information checked on 18 November 2026. Call the provider before visiting; clinicians, schedules, services, and fees can change.'),
 ('How can I report an outdated link or suggest a resource?','Use the <a href="contact.html?subject=Request+a+Resource">contact form</a> and include the page URL, provider name, and proposed correction. Avoid sending private medical information.'),
 ('Can I save a guide as a PDF?','Each article has a Print / save as PDF button. Choose Save as PDF in your browser’s print dialog, or print a paper copy.')])+'</section><div class="guide-note">Educational resources, not individual treatment. Our guides have not been clinically reviewed. Discuss clinical concerns with a qualified speech-language professional.</div></main>'
(ROOT/'resources.html').write_text(page('Free stuttering resources & worksheets','Free speech support worksheets, trusted educational resources, and links to speech therapy in Bangladesh.',body))
print('Rendered 23 articles, blog, resources, 14-entry directory, and 4 editable worksheets.')
