(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>https://fluent-minds.netlify.app/'+escape(path)+'</loc></url>\n' for path in paths)+'</urlset>\n')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /admin/\nSitemap: https://fluent-minds.netlify.app/sitemap.xml\n')
